input.sparql:
SELECT ?equip ?point ?setpoint
WHERE {
  ?equip (brick:hasPoint|brick:hasPart/brick:hasPoint) ?point .
  ?equip brick:isPartOf+ brick:Core_top .
  ?point rdf:type brick:Temperature_Sensor .
  ?setpoint (brick:setpointHasSensor|brick:hasPoint/brick:hasPoint/brick:hasSensor) ?point ;
           rdf:type brick:Temperature_Setpoint .
}
